<template>
  <q-select
    dense
    borderless
    class="input-text-28px"
    :loading="language_origins_loading"
    v-model="language_origin"
    :options="origin_list"
    emit-value
    map-options
    :disable="isReadOnly"
    :label="$t('amount_format')"
    @update:model-value="dropdownChanged"
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip v-if="scope.opt.description">
            <span v-html="scope.opt.description"></span
          ></q-tooltip>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useLangOriginDropdownStore } from 'src/store/main';

export default defineComponent({
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    origin: {
      type: String,
      default: '',
    },
    column_name: {
      type: String,
      default: '',
    },
  },
  mixins: [],
  components: {},
  emits: ['updateColumnOrigin'],
  watch: {
    language_origins_loading: {
      handler: function (newVal, oldVal) {
        if (newVal == false) {
          this.updateOriginList();
        }
      },
    },
  },
  data() {
    return {};
  },
  mounted: function () {
    this.updateOriginList();
  },
  methods: {
    dropdownChanged() {
      if (this.column_name == '') return;
      if (this.language_origin == '') return;

      this.$emit('updateColumnOrigin', {
        column_name: this.column_name,
        origin: this.language_origin,
      });
    },
    updateOriginList() {
      if (!this.language_origins_loaded) return;
      this.origin_list = JSON.parse(JSON.stringify(this.language_origins));
      this.origin_list[0].label = this.$t('auto');
      this.origin_list[0].value = 'auto';

      this.language_origin = this.origin;
    },
  },

  setup() {
    const language_origin_dropdown = useLangOriginDropdownStore();
    const {
      language_origins,
      language_origins_loading,
      language_origins_loaded,
    } = storeToRefs(language_origin_dropdown);

    return {
      language_origins_loaded,
      language_origins_loading,
      origin_list: ref([] as any),
      language_origin: ref(''),
      language_origins,
    };
  },
});
</script>
<style lang="scss">
.language-select {
  width: 130px;
}
</style>
