<template>
  <q-card style="width: 700px; max-width: 1060px; height: 460px">
    <q-card-section class="row items-center q-pb-none"> </q-card-section>
    <q-card-section>
      <div class="table-container col-sm-12 col-md-12 col-lg-12 min-height-300">
        <q-table
          class="my-sticky-header-table"
          :no-data-label="$t('no_record_found')"
          :rows="rows"
          :columns="columns as any"
          :rows-per-page-options="[0]"
          row-key="name"
          :filter="filter"
        >
          <template v-slot:top>
            <div class="bg-white">
              <q-input
                class="float-right"
                outlined
                debounce="300"
                color="primary"
                v-model="filter"
                :label="$t('search_by_column')"
              >
                <template v-slot:append>
                  <q-icon name="search" />
                </template>
              </q-input>
            </div>
          </template>
          <template v-slot:body-cell-name="props">
            <q-td :props="props">
              {{ props.row.label }}
            </q-td>
          </template>
          <template v-slot:body-cell-action="props">
            <q-td :props="props">
              <f-btn
                icon="add"
                :label="$t('enable')"
                @click="enableColumn(props.row.name)"
              />
            </q-td>
          </template>
        </q-table>
      </div>
    </q-card-section>
  </q-card>
</template>

<script setup lang="ts">
/**
 * BlockedColumns - Display and manage blocked table columns
 * Converted to Composition API with type-safe defineProps
 */
import { ref, onMounted } from 'vue';
import { useTranslate } from '@tolgee/vue';

interface TableColumn {
  name: string;
  label: string;
  field: string;
  align: 'left' | 'right' | 'center';
}

defineProps<{
  rows: Array<{ name: string; label: string }>;
}>();

const { t } = useTranslate();

const filter = ref('');
const columns = ref<TableColumn[]>([]);

function prepareColumns() {
  columns.value.push({
    name: 'name',
    label: t.value('column_name'),
    field: 'name',
    align: 'left',
  });
  columns.value.push({
    name: 'action',
    label: t.value('action'),
    field: 'action',
    align: 'right',
  });
}

function enableColumn(columnName: string) {
  const event = new CustomEvent('enable_custom_column', {
    detail: columnName,
  });
  document.dispatchEvent(event);
}

onMounted(() => {
  prepareColumns();
});
</script>

