<!--vbase-->
<template>
  <!-- Regex List -->
  <q-dialog
    persistent
    v-model="showDialog"
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card style="width: 1000px; max-width: 1060px; height: 600px">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('manage_regexes') }}</span>
        </q-toolbar-title>

        <q-btn
          flat
          round
          dense
          icon="close"
          v-close-popup
          @click="setShowRegexDlg"
        />
      </q-toolbar>
      <q-card-section class="row items-center q-pb-none"> </q-card-section>

      <q-card-section>
        <div class="full-width q-mb-md">
          <q-btn
            v-if="validate_pattern === true"
            color="orange"
            class="mr-6 float-right"
            :label="$t('validate')"
            @click="validatePattern()"
          />
          <q-btn
            v-if="allowSave === true"
            class="mr-6 float-right bg-primary text-white"
            :label="$t('save_changes')"
            @click="saveAll()"
          />
        </div>
      </q-card-section>
      <q-card-section>
        <div class="table-container full-width min-height-300">
          <q-markup-table>
            <thead>
              <tr>
                <th class="text-left">{{ $t('regex') }}</th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(row, index) in regexList" :key="row['key']">
                <td class="text-left">
                  <q-input
                    dense
                    borderless
                    tabindex="0"
                    :data-id="row['key']"
                    :class="
                      !row.validate || row.required_error
                        ? 'column-error-border'
                        : ''
                    "
                    v-model="regexList[index].value"
                    @update:model-value="
                      (val: any) => {
                        inputValueChanges(val, Number(index), row['key']);
                      }
                    "
                  >
                    <template v-slot:append>
                      <q-icon
                        v-if="!row.validate || row.required_error"
                        flat
                        dense
                        name="error"
                        size="24px"
                        color="red"
                      >
                        <q-tooltip class="bg-red line-error-tooltip">
                          <template v-if="!row.validate">
                            {{ $t('pattern_invalid') }}
                          </template>
                          <template v-if="row.required_error">
                            {{ $t('pattern_empty') }}
                          </template>
                        </q-tooltip>
                      </q-icon>
                    </template>
                  </q-input>
                </td>
              </tr>
              <tr v-if="!regexList || regexList.length < 1">
                <td class="text-center">
                  {{ $t('no_data_found') }}
                </td>
              </tr>
            </tbody>
          </q-markup-table>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <!-- END Regex List -->
</template>

<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { useDocumentStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { documentRegexesApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    loading_new_data: {
      type: Boolean,
      default: false,
    },
    showRegexDlg: {
      type: Boolean,
      default: false,
    },
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    const docStore = useDocumentStore();

    return {
      docStore,
      loading: ref(true),
      allowSave: ref(false),
      showDialog: ref(false),
      regexList: ref([] as any),
      validate_pattern: ref(false),
    };
  },
  watch: {
    loading_new_data: {
      handler: function (newVal, oldVal) {
        if (newVal === true) {
          this.loading = newVal;
        }
      },
    },
    showRegexDlg: {
      handler: function (newVal, oldVal) {
        if (newVal === true) {
          this.showDialog = newVal;
          this.loading = !newVal;
          this.convertMapintoArray();
        }
      },
    },
  },

  methods: {
    inputValueChanges(new_val: any, index: number, ruleId: string) {
      if (new_val === this.docStore.regex.get(ruleId)) {
        return;
      }

      this.validate_pattern = true;
      this.allowSave = false;

      if (new_val === '') {
        this.regexList[index].validate = false;
        this.regexList[index].required_error = true;
      } else {
        this.regexList[index].validate = true;
        this.regexList[index].required_error = false;
      }
    },
    saveAll() {
      if (!this.validateData()) {
        return;
      }
      this.allowSave = false;
      this.showDialog = false;
      this.updateStoreRegexMap();
      this.$emit('updateRegexByRule');
    },
    updateStoreRegexMap() {
      this.regexList.forEach((row: any, index: any) => {
        if (this.docStore.regex.has(row.key)) {
          this.docStore.regex.set(row.key, row.value);
        }
      });
    },
    validateData() {
      let has_error = true;
      if (this.validate_pattern) {
        has_error = false;
        notify.error('Please validate Before save.');
      }
      if (this.regexValuePatternsEmpty()) {
        has_error = false;
        notify.error('Pattern field is required');
      }

      return has_error;
    },
    regexValuePatternsEmpty() {
      let has_empty = false;
      this.regexList.forEach((row: any, index: any) => {
        if (!row.value || row.value === '') {
          row.required_error = true;
          has_empty = true;
        } else {
          row.required_error = false;
        }
      });
      return has_empty;
    },
    dispatchSuccessEvent() {
      const event = new CustomEvent('regexes_saved', { detail: this.doctype });
      document.dispatchEvent(event);
    },

    async validatePattern() {
      try {
        if (this.regexValuePatternsEmpty()) {
          notify.error('Pattern field is required');
          return;
        }
        this.showLoading();
        const response = await documentRegexesApiService.validatePattern(
          this.getValidatePatternData(),
        );
        if (response.success === false) {
          throw { message: response.message };
        }
        this.validate_pattern = false;
        this.allowSave = true;
        this.updateRows(response.data);
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
      } finally {
        this.hideLoading();
      }
    },

    updateRows(result: any) {
      for (let [pattern, validate] of Object.entries(result)) {
        this.regexList.forEach((row: any, index: any) => {
          if (row.value == pattern) {
            const new_validate = validate === false ? false : true;
            row.validate = new_validate;
            if (new_validate === false) {
              this.validate_pattern = true;
              this.allowSave = false;
            }
          }
        });
      }
    },
    getValidatePatternData() {
      let regexes = [] as string[];
      this.regexList.forEach((row: any, index: any) => {
        const regex =
          !row.value || row.value === '' ? '' : row.value.toString();
        regexes.push(regex);
      });

      return regexes;
    },
    convertMapintoArray() {
      this.regexList = Array.from(this.docStore.regex, ([key, value]) => {
        return {
          ['key']: key,
          ['value']: value,
          ['validate']: true,
          ['required_error']: false,
        };
      });
    },
    setShowRegexDlg() {
      this.$emit('setShowRegexDlg', false);
    },
  },
});
</script>

<style lang="scss" scoped>
.column-error-border {
  border: 1px solid red;
}
</style>
