<template>
  <q-select
    dense
    borderless
    class="input-text-28px"
    v-model="extract_origin"
    :options="extract_list"
    emit-value
    map-options
    :disable="isReadOnly"
    label="Extract From"
    @update:model-value="dropdownChanged"
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip v-if="scope.opt.description">
            <span v-html="scope.opt.description"></span
          ></q-tooltip>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    origin: {
      type: String,
      default: '',
    },
    column_name: {
      type: String,
      default: '',
    },
  },
  mixins: [],
  components: {},
  emits: ['updateExtractOrigin'],
  //  watch: {
  //    extract_origins_loading: {
  //      handler: function (newVal, oldVal) {
  //        if (newVal == false) {
  //          this.updateOriginList();
  //        }
  //      },
  //    },
  //  },
  data() {
    return {};
  },
  mounted: function () {
    this.extract_origin = this.origin;
  },
  methods: {
    dropdownChanged() {
      if (this.column_name == '') return;
      // if (this.extract_origin == '') return;

      this.$emit('updateExtractOrigin', {
        column_name: this.column_name,
        origin: this.extract_origin,
      });
    },
  },

  setup() {
    const extract_list = ref([
      { label: '', value: '' },
      { label: 'Above', value: 'above' },
      { label: 'Below', value: 'below' },
    ]);
    return {
      origin_list: ref([] as any),
      extract_origin: ref(''),
      extract_list,
    };
  },
});
</script>
<style lang="scss">
.language-select {
  width: 130px;
}
</style>
